final=analysis.save_snapshot()
fresh=final['workbook_rows']['Fresh evaluation']
esc=lambda x:html.escape(str(x),quote=True)
def table(headers,rows):
    return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+esc(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(r[h])+'</td>' for h in headers)+'</tr>' for r in rows)+'</tbody></table></div>'
score_rows=[{'Evidence':'Fresh runs with original dataset labels','Baseline':'92/100','Revised':'94/100','Delta':'+2 pp','Wins':8,'Regressions':6},
    {'Evidence':'Fresh runs with participant-reviewed labels','Baseline':'93/100','Revised':'93/100','Delta':'0 pp','Wins':7,'Regressions':7},
    {'Evidence':'Repository broader revision, separate reference exercise','Baseline':'92/100','Revised':'97/100','Delta':'+5 pp','Wins':8,'Regressions':3}]
approvals=[{'Review set':name,'Approved failures':m['approved_failed_cases'],'Failed cases':m['failed_cases'],'Pending':m['pending_failed_cases']} for name,m in final['reviewed_metrics'].items()]
